actions.body:
{
  "type": "message",
  "attachments": [
    {
      "contentType": "application/vnd.microsoft.card.adaptive",
      "contentUrl": null,
      "content": {
        "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
        "type": "AdaptiveCard",
        "version": "1.4",
        "body": [
          {
            "type": "TextBlock",
            "size": "Medium",
            "weight": "Bolder",
            "text": "Approval requested: {{issue.key}}",
            "wrap": true
          },
          {
            "type": "TextBlock",
            "text": "{{issue.fields.summary}}",
            "wrap": true
          },
          {
            "type": "FactSet",
            "facts": [
              {
                "title": "Type",
                "value": "{{issue.fields.issuetype.name}}"
              },
              {
                "title": "Priority",
                "value": "{{#if issue.fields.priority.name}}{{issue.fields.priority.name}}{{else}}None{{/if}}"
              },
              {
                "title": "Reporter",
                "value": "{{#if issue.fields.reporter.displayName}}{{issue.fields.reporter.displayName}}{{else}}Unknown{{/if}}"
              },
              {
                "title": "Project",
                "value": "{{issue.fields.project.name}}"
              }
            ]
          }
        ],
        "actions": [
          {
            "type": "Action.OpenUrl",
            "title": "Approve or decline in the portal",
            "url": "{{_flow.JSM_PORTAL_URL}}/browse/{{issue.key}}"
          },
          {
            "type": "Action.OpenUrl",
            "title": "Open in Jira",
            "url": "{{baseUrl}}/browse/{{issue.key}}"
          }
        ]
      }
    }
  ]
}
